export function Home() {
  const lessons = __container.get<LessonService>(LessonService);
  useSyncExternalStore((cb) => lessons.__subscribe(cb), () => lessons.__getVersion());
  const [menuOpen, setMenuOpen] = useState(false);
  const [starterLessons, setStarterLessons] = useState([]);
  const [batchLessons, setBatchLessons] = useState([]);
  const [formsLessons, setFormsLessons] = useState([]);
  const ngOnInit = () => {
    setStarterLessons(lessons.lessons.filter((l: Lesson) => l.id <= 5));
    setBatchLessons(lessons.lessons.filter((l: Lesson) => l.id >= 6 && l.id <= 25));
    setFormsLessons(lessons.lessons.filter((l: Lesson) => l.id >= 26));
  };
  const openMenu = () => {
    setMenuOpen(true);
  };
  const closeMenu = () => {
    setMenuOpen(false);
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  return (
    <RgSection>
      {/* (menu) has no standard RN prop, mapped to onMenu */}
      <RgAppbar title="Rangular Tutorial" titleAlign="center" menu onMenu={() => openMenu()} />
      <RgDrawer open={menuOpen} onClose={() => closeMenu()}>
        <RgText variant="title">Rangular Tutorial</RgText>
        <RgList>
          <RgRow title="Home" subtitle="The lesson list" onPress={() => __router.navigateByUrl("/home")} />
          <RgRow title="About" subtitle="What this app is and how it grows" onPress={() => __router.navigateByUrl("/about")} />
        </RgList>
        <RgText variant="bodyLarge">Rangular framework 0.1.2</RgText>
      </RgDrawer>
      <RgText variant="display">Learn Rangular</RgText>
      <RgText variant="bodyLarge">Short lessons, in order. Each lesson has a plain explanation, a Code block, and a live demo running on the same screen.</RgText>
      <RgCard>
        <RgText variant="title">How to use this tutorial</RgText>
        <RgText variant="bodyLarge">Start at Lesson 1 and go in order. Tap a lesson, read it, try its demo, then come back for the next one. New lessons arrive in batches, and the list below always shows what is ready. The menu at the top left holds the About screen.</RgText>
      </RgCard>
      <RgText variant="label">Getting started: lessons 1 to 5</RgText>
      <RgList>
        {starterLessons.map((l, index) => (
          <RgRow key={l?.id ?? index} title={l.title} subtitle={l.subtitle} time={l.minutes} onPress={() => __router.navigate(['/lesson', l.id])} />
        ))}
      </RgList>
      <RgText variant="label">Components and templates: lessons 6 to 25</RgText>
      <RgList>
        {batchLessons.map((l, index) => (
          <RgRow key={l?.id ?? index} title={l.title} subtitle={l.subtitle} time={l.minutes} onPress={() => __router.navigate(['/lesson', l.id])} />
        ))}
      </RgList>
      <RgText variant="label">Forms and interaction: lessons 26 to 45</RgText>
      <RgList>
        {formsLessons.map((l, index) => (
          <RgRow key={l?.id ?? index} title={l.title} subtitle={l.subtitle} time={l.minutes} onPress={() => __router.navigate(['/lesson', l.id])} />
        ))}
      </RgList>
      <RgCard>
        <RgText variant="title">Coming next</RgText>
        <RgText variant="bodyLarge">The next batch is services, routing, and data: services and dependency injection, routing in depth, HttpClient over fetch, signals and reactive services, and a small real app built lesson by lesson as the capstone. Later batches follow the Angular documentation, topic by topic, each with its Rangular equivalent.</RgText>
      </RgCard>
    </RgSection>
  );
}

