export function ChipsDemo() {
  const [filters, setFilters] = useState(['Unread', 'Has attachment', 'Starred']);
  const [unread, setUnread] = useState(3);
  const [storageUsed, setStorageUsed] = useState(60);
  const [syncing, setSyncing] = useState(false);
  const removeFilter = (name: string) => {
    setFilters(filters.filter((f: string) => f !== name));
  };
  const markAllRead = () => {
    setUnread(0);
  };
  const less = () => {
    setStorageUsed(storageUsed - 10);
  };
  const more = () => {
    setStorageUsed(storageUsed + 10);
  };
  const onSync = (value: boolean) => {
    setSyncing(value);
  };
  return (
    <>
      <RgText variant="label">Filters</RgText>
      <RgChips>
        <RgChip icon="star">Starred only</RgChip>
        {filters.map((f, index) => (
          <RgChip key={f?.id ?? index} removable onRemove={() => removeFilter(f)}>{f}</RgChip>
        ))}
      </RgChips>
      {(filters.length === 0) && (
        <RgText variant="bodyLarge">All removable filters are gone.</RgText>
      )}
      <RgText variant="label">Mail</RgText>
      <RgRow title="Inbox" subtitle="Your mail at a glance" badge={unread} />
      <RgButton badge={unread} onPress={() => markAllRead()}>Mark all read</RgButton>
      <RgText variant="label">Storage: {storageUsed}%</RgText>
      <RgProgressBar value={storageUsed} />
      <RgButton disabled={(storageUsed === 0)} onPress={() => less()}>Use 10 less</RgButton>
      <RgButton disabled={(storageUsed === 100)} onPress={() => more()}>Use 10 more</RgButton>
      <RgSwitch checked={syncing} onChange={($event) => onSync($event)}>Syncing</RgSwitch>
      {syncing && (
        <RgSection>
          <RgSpinner />
          <RgText variant="bodyLarge">Syncing now. While the work has no number, a spinner speaks.</RgText>
        </RgSection>
      )}
    </>
  );
}

