export function FormControlDemo() {
  const [applied, setApplied] = useState('');
  const inviteFormRef = useRef(new FormGroup({
    code: new FormControl('', [Validators.required, Validators.minLength(4)]),
  }));
  const [, setFormVersion] = useState(0);
  useEffect(() => {
    const subs = [
      ...Object.values(inviteFormRef.current.controls).map((control) => control.valueChanges.subscribe(() => setFormVersion((v) => v + 1))),
    ];
    return () => { subs.forEach((sub) => sub.unsubscribe()); };
  }, []);
  const useSample = () => {
    inviteFormRef.current.get('code').setValue('YOGA10');
  };
  const clear = () => {
    inviteFormRef.current.get('code').setValue('');
  };
  const apply = () => {
    setApplied(String(inviteFormRef.current.get('code').value));
  };
  return (
    <>
      <View>
        <RgInput label="Invite code" placeholder="At least 4 characters" value={inviteFormRef.current.get('code').value} onChangeText={($event) => inviteFormRef.current.get('code').setValue($event)} onBlur={() => { inviteFormRef.current.get('code').markAsTouched(); setFormVersion((v) => v + 1); }} />
        <RgText variant="bodyLarge">Value: {inviteFormRef.current.get('code').value}</RgText>
        <RgText variant="bodyLarge">Valid: {(inviteFormRef.current.get('code').valid ? 'yes' : 'no')}</RgText>
        <RgText variant="bodyLarge">Touched: {(inviteFormRef.current.get('code').touched ? 'yes' : 'no')}</RgText>
        <RgText variant="bodyLarge">Dirty: {(inviteFormRef.current.get('code').dirty ? 'yes' : 'no')}</RgText>
        <RgButton onPress={() => useSample()}>Use a sample code</RgButton>
        <RgButton onPress={() => clear()}>Clear</RgButton>
        <RgButton disabled={inviteFormRef.current.invalid} onPress={() => { inviteFormRef.current.markAllAsTouched(); setFormVersion((v) => v + 1); apply(); }}>Apply code</RgButton>
      </View>
      {applied && (
        <RgText variant="bodyLarge">Applied code: {applied}</RgText>
      )}
    </>
  );
}

